public class T58 {
    static String status = "";
    static class Lock implements AutoCloseable {
        Lock() { status += "L"; }
        public void close() { status += "U"; }
    }
    static int compute(int x) {
        try (Lock l = new Lock()) {
            if (x < 0) return -1;
            status += "W";
            return x * 2;
        }
    }
    public static void main(String[] args) {
        int r = compute(3) + compute(-1);
        System.out.println(r + " " + status);
    }
}
